WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (126::BIGINT, 'La GOAT es la profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'ee9760cc35f93546ed6daee8d8dc889a258c641f9bd66e882288357e32d5c701'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Todo es en grupo. La profe hace la clase interesante pero eso no cambia el hecho de que es un seminario y se siente como una pérdida de tiempo. Todos los trabajos se hacen en clase. Es la mejor opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '69a52eb919145341f6546c849a71195f41c93f99c2c90cb554a415af35740305'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Muy buena persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '0b8e190fd6715a7a2349b3f27e56eff192336a4974599d691b7ed913ed4e5323'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Ella es un amor de persona, hace chistes y crea un ambiente agradable, eso si califica un poco duro y es bastante estricta con la asistencia. No falte a ninguna clase, sino pierde un porcentaje significativo de la nota, y consigase un buen grupo de trabajo, esto es MUY necesario.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4cdf10b1e561e745d541d6b5567135ae9d376059667c277bb1707656048d971f'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es un amor, solo haga todos los trabajos pero consígase un buen grupo de trabajo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, '8dfb0508176e729d4c9a6166a92eeb81dbbdfef59acecc4dffd437c0d868df6c'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es un curso al que muchos no le toman importancia, pero ella lo imparte vacilón y curiosamente termina gustando volviéndose llevadero.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-30T00:00:00+00:00'::TIMESTAMPTZ, '76ce6cf8370efc4ab15478eeb7d9b56d833d54ff61745d3873c99e31478a7bc9'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es muy buena, nada mas haga las lecturas y trabajos, no son dificiles solo hay que leer y saber citar APA. Si o si necesita un dispositivo, telefono/tablet/ preferiblemente compu, para hacer los trabajos que se hacen en clase y se entregan en clase.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '7e3431ff726c54fcb9f1a24984f2ca44681acd13d60a00e57c6aeea4077691d8'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es excelente, muy graciosa, está muy interesada en que ud aprenda. Se toma muy en serio las evaluaciones pero califica justo. Hay que entregar trabajos en el horario de la clase, todo se hace en grupo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '5ca0cfa4f1a026a5cfedca7cc3a164bfe0954e08f3bbded1c2dcf2ad9f4e277b'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Una excelente profesora, cae demasiado bien y es demasiado graciosa, genera interés en la clase. Sí hay que leer y sepa que si se va a aprender quien es ud y le toca trabajar pero siempre ayuda y los trabajos son fáciles. De las mejores profes que hay, super ambiente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2024-11-23T00:00:00+00:00'::TIMESTAMPTZ, '0a5cfc6ff074e6d4e3d5651ce4c4789aaadd51bd355256c8111f3c93eba0020c'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es muy divertida y pone evaluaciones fáciles. Eso sí, hay que presentar en cada clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'f178077873be82359605280c52385e1f9252d36cdf6c1e9e8d9cb420f7a740cf'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'El curso en si nunca va a despertar el interés del estudiante ya que por naturaleza quita mucho tiempo y no tiene nada que ver con ninguna carrera. Sin embargo, esta profe hace que al menos uno pase un buen rato en su clase y deja trabajos muy sencillos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '3e4be6113047de309096c913a6b06bfdeeccdd655ccd4bb63272a4060e0e01d2'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, '!!LLEVELO EN VERANO¡¡ Un curso que no vale la pena, abarca tiempo innecesario que uno necesita en el semestre, la profe es buena gente, sin embargo considero que le falta claridad, nunca me saltó el interés por la clase, siento que es aburrido y que los temas no se abarcan de una forma interesante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2024-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'e5de1679d39be95e07e639625e98409939047f663461c5b1c0c3981cf9f3aa00'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es fácil pasar el curso con ella, pero es importante tener un buen grupo de trabajo y ademas tener mucho cuidado con las normas APA. Se hacen trabajados practicamente todas las semanas pero los que se hacen en clase no son muy dificiles'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Brinda apoyo']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b59fc1b99601334b07381281ef8b31da72cdc6596f00e66ae02e7827af956f6b'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es un amor, y es divertida. Deja trabajos casi todas las semanas y es estricta con la revisión y las citas y referencias (en serio revisa con mucho ojo eso), pero todo eso es muy útil por la retroalimentación. Es muy facil pasar con excelente nota. La asistencia es muy importante'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '78b0145e2b76eb077d7835dd9be0d4de791d5c747da25b2dd5e169558507f2de'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profesora es cómica. Todas las semanas hay cosas por hacer, todo debe exponerse, hay bastantes lecturas. Es bastante estricta con el tema de la asistencia.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '791a952bc3dff32bca0855d4c2bc0fb44291a3558d746e22731d4becb65682d0'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Cursos como estos siempre quitan tiempo y son molestos, pero esta profe le mete a uno el interés suficiente para salir sobrado del curso. Leer bastante, pero los trabajos son sencillos si agarra buen grupo, exponer cada semana pero la profe califica suave si sigue la rubrica. Recomendada'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'fd559912602400da0bf99735d2bdb0ba0fcf9b8afe36507042e79159ad028a45'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Harta de este curso, es fácil pero la carga no tiene sentido, es un curso que se lleva porque lo ocupamos para graduarnos no porque nos interesa. Los trabajos son una estupidez, fáciles, rápidos, pero todas las semanas hay algo que hacer.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'fff717956eb2e512cfa20a36d99e43c84b8359336f158bb34edab4379c008ad5'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'El curso como tal es bastante sencillo. Hay que hacer un trabajo semanal pero las lecturas nunca superan las 10 páginas y tampoco son complicadas. La clase es básicamente exponer el trabajo entonces se sale bastante antes. La profe como tal es muy vacilona y cómica. Es un curso interesante al fina'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases largas']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'fad630fc146f37b5bc39033a22a86c4759a30eb614422734ea92c09be50818ee'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Excelente persona y profe. Sin embargo, el curso quita mucho tiempo porque así es, todas las semanas hay lecturas y hay que hacer estudios de casos (2), trabajos colaborativos (3), trabajos autónomos (5) y la monografía. Con la profe TODO se expone, si le dan nervios mejor buscar otrx, y pasa lista.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '076b140855d2c39216c4ce258d9abbc02d6337a6f26fc7ad9a28bc86d2549155'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Parece más un curso de redacción, de "Seminario" sólo el nombre. Si citas mínimamente mal lo cuenta como plagio, y nada de lo que uno pone le parece. Quita tiempo, siempre hay algo que hacer todas las semanas y todo es en grupo. Comparada con otros está bien, pero no es nada agradable el curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'a99f22b9c8ffe8c51c51428364e3f8bbce645c0c13322319d0d3ed0418a46cec'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es excelente. Explica con claridad lo que quiere en cada trabajo, eso sí, son trabajos semanales (lecturas). Todos los trabajos se presentan por eso se debe asistir a las clases. Muy organizada. En calificar, es ruda, pero lo normal.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-05-29T00:00:00+00:00'::TIMESTAMPTZ, '7c2c1ba606abeefd6fbf1ea0e20c5131ac2a0f46dded5a0204ab7a383601a14f'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es todo lo contrario... Me embargue y casi todos sus estudiantes llevamos malas notas .... Aparte que exige APA como si no hubiese un mañana y no usa APA como lo exige la ley si no a manera de ella y si haces algo mal 0 en todo el trabajo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-03-29T00:00:00+00:00'::TIMESTAMPTZ, 'bb44f8ced75adb145b383c3a2cbf8e477eb285870af05f94baf15ccff4f69cdf'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Excelente como profesora y un amor como persona. Hay que leer pero no tanto como con otros profes. En las clases por lo general se expone o se hacen trabajos cortos en grupo, que no se califican duro siempre y cuando sea coherente. Para los trabajos escritos se debe tener mucho cuidado con el APA'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-07T00:00:00+00:00'::TIMESTAMPTZ, '30a2b1bb6bcf31c35de7d116d35a4ad9f3a29c7d447e703a4cf3baca2bb7e4fa'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es muy buena gente, en general las clases son hacer presentaciones grupales pero no las califica tan duro aunque, con los trabajos escritos si hay que tener cuidado porque si los califica duro y se fija mucho en la ortografía y la coherencia de lo escrito.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2022-12-27T00:00:00+00:00'::TIMESTAMPTZ, 'f8da5fbe5aec80a68a3488a924ece8f9f7252b748e5043a8b5526af4b5f4e286'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'El curso es bastante sencillo, pero si es necesario poner mucha atención en el formato APA y en la puntuación de los trabajos escritos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, '3e21b613a42459d0d1370b99747a5b1c3faa81e6c063b4e54ecf7496d4583cde'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es un amor. El curso no se hace tan pesado aunque sí hay que exponer y escuchar bastantes exposiciones. Es bastante rigurosa con el formato APA de las investigaciones, pero el curso se pasa fácil y no demanda tanto tiempo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'dea4461188ea092860ea9c5a7d0927126dfc15a26dbe61a2555079b6ef2b99ae'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es buena, pero califica hasta las comas, así que la calificación no es objetiva, si no lo que a ella le parezca correcto. Hay que hacer todo en grupo y ella casi no da clases, el 80% de las clases son otros grupos exponiendo.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Requiere mucha lectura']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, '35808372e39d19f1df84f4c103c9d53ad210405b2122186ac74c37adfdd87168'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Excelente profesora, da instrucciones claras de lo que quiere y evalúa acorde a ello. Es justa y empática en situaciones personales. Hace la materia muy interesante. Se hacen dos ensayos con base a lecturas y una exposición grupal que va con una monografía (escoja sabiamente el grupo).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-10T00:00:00+00:00'::TIMESTAMPTZ, '346006713e1548b9abac3c6f1d4c184c54e61cb044eef2c12934b70c236e9ac8'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es buena gente, solo que califica bastante rudo, suele fijarse en todo y baja muchos puntos por eso, hay que ser bastante cuidadoso y entregar todos los trabajos.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ad05664c9553e9fa7f260e43d628a4a953afd789d326799e878a7ae21bdab160'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es muy buena , muy amable y cómica , pero califica medio rudo , se fija en todo , comas , puntos , tildes y aveces castiga mucho por esos aspectos ! En lo demás es muy buen y exelente persona'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, '4b7b8d66dc529c6bc645f015357d1da4649eaf1a6edba2c933c7f01af8c4c40c'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'De las mejores profes que he tenido en el tec, el curso se presta para leer mucho pero ella hace que las clases sean muy interactivas y se aprende lo justo y necesario. Desde el primer dia se tiene el cronograma de los trabajos lo que permite avanzarlos con tiempo y las instrucciones siempre muy cla'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '9997d98393cbf4325bcc838940f39916675c8680c425db8ace3c34a4ef46755f'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es excelente y da buena retroalimentación en los trabajos. La materia en sí no es muy entretenida, pero al menos no la vuelve tediosa. Importante a tener en cuenta, ABSOLUTAMENTE TODOS LOS TRABAJOS DEL CURSO son en grupo (el grupo es hecho el primer día)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd6908887474bd8a91d4f3827642b42ab15f0be2d9915aa5bf67ba753004d51b4'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es muy buena y atiende todas las dudas claramente y es una gran persona. La materia de seminario es aburrida en su mayoría y TODO es en grupo, no les recomiendo que se metan solos porque les puede tocar un grupo asqueroso. Aun así los trabajos son fáciles y la profe califica suave'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9ea9dbb321746d2bf9631596103db156669f2be5fb87c6e0ce290be44bfc95c0'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profe es bastante buena, y hace el curso interesante. Tome en cuenta que los trabajos que más valen son en grupo, entonces debería matricular con gente conocida para hacer un buen trabajo a través del curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'La participación importa', 'Brinda apoyo']::TEXT[], '2020-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'f950c35f9ce75e817592f99a85867ea1cff3c47ab584a5417662bbc504607bd0'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La profesora es muy buena, si va a matricular en la modalidad virtual, y matricula solo, mejor no lo haga, le pueden tocar con personas que no realizan bien su trabajo, afectandolo directamente a usted en su nota'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-05T00:00:00+00:00'::TIMESTAMPTZ, '663d16b9fccbc576429c0fdf494c0f6e3587d25e2f5b014d1f61122679db349b'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La recomiendo al 100% para llevar el curso, evaluaciones claras, una organización impecable para llevar todas las clases y una retroalimentación excelente en cualquier entrega realizada. Aprendí a corregir muchas faltas que yo tenía en mis entregas y estoy seguro que volvería a matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '76daf5ae4723b36611ff967da9f201208235a6b3a9308df8606deac47f2df737'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Desarrolló la modalidad virtual muy bien. Hay tareas todas las semanas pero se hacen rápido, la mayoría de los aspectos del curso se trabajan en grupo. Responde muy rápido y busca ayudar al estudiante en todo lo que pueda. Califica suave y muy claro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '0b9ce2366fbef6fa6c31a223f206cd011686908101e6bc019404ef60d4e79c7a'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Deja tareas toooodas las semanas y aunque no es dificil quita tiempo, si hay que ponerle. Los grupos que hacen el primer día son para siempre entonces tenga cuidado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2020-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'cd2cf6f067aedcea2da1f6af514ba14068eefc0b3733540eb05dde11f9791cfa'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Excelente profesora para llevar ese curso. La mayoría de trabajos se hacen en clase, y con tener una buena hablada de paja, se pasa fácil. Lo profe es muy carismática'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, '810402f864b0c931f7d108c3bc550384fa13b797cc9d34ff7d42e2b63ded24bc'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'El curso es fácil, solamente se debe hacer muchas tareas y dos ensayos más o menos largos. Pero en general, la recomiendo y las clases son vacilonas a veces.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, '258e34c743862f5d12769914fcfb30822ed5268d713e60ca10ba0c98a540650b'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es muy graciosa y sarcástica. Califica un poco duro, revisa cada mínimo detalle de los trabajos. Deja tareas cortas o trabajos para hacer en clase de 2% y 3 trabajos grupales un poco más largos. Se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Aspectos de calificación claros']::TEXT[], '2019-10-23T00:00:00+00:00'::TIMESTAMPTZ, '04a6a8ce3686b7d66a831d5d6ceae21949fe96bb22952b49f9bc0ed110f75e95'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La mejor profe para este curso. 100% recomendada. Aunque el curso suena aburrido, la profe hace la clase bastante entretenida y hasta dan ganas de ir. Deja varios trabajos, pero la mayoría se hacen en grupos y son super fáciles y rápidos de hacer.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'c73409e32b4d902cab3ce8b1b8c40e1be04e9f0d93511dc745c0bb3b4224baf5'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Buena profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '1243f4fef1b99e35a69cba728eb032a41dfb2aedfc8b6236a209c8a98c15b988'::TEXT, ARRAY[980]::BIGINT[]),
    (126::BIGINT, 'La profe es un poco loca pero en el buen sentido, se expone 3 veces en total, hay que leer lecturas para las exposiciones y se hace un trabajo en cada clase de 2%.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '3a2ec2af55ebb84ee1f36aeb04aa099b4a8bd9d8a3ad478c8f10aa5090547b2d'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (126::BIGINT, 'La profe al inicio es un poco intensa (especialmente con usar el celular), pero luego se va soltando y agarrando confianza. Es bien loca. Normalmente se hacen en clase los trabajos. Califica relativamente duro, no le gusta regalar la nota. En general las clases son sencillas y dinámicas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '26b39b6fc9aa2d943d88a81deff85abef380d1ede109d28287c5cd98ea6770e2'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-19T00:00:00+00:00'::TIMESTAMPTZ, '2b395f4164d1d3cb72b28f3699e9329383f21be1fd9b0d340adc403d0d7467a0'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'e9d5fcba18f2c8a08a307f31cf746055beeefabf288a78a38c409add804aef30'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es muy buena nota y la mayoría del trabajo en es clase, entonces no se pierde mucho tiempo libre. Aunque también en muchos de estos cursos la experiencia de uno puede variar dependiendo del grupo que tenga, en sí la profe es muy buena.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '0f354bb707d3a7f92f567ba4c8f75c06e795b5646f5273cf270d4405903bdb28'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Demasiado buena y adorable'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'c96fe8276389ebdd04e4c9a1476c36871fd6487be5267a3649122af0b11a5f9c'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'La mejor profe de seminario, divertida loca y amable, se pasa sencillo haciendo bien todos los trabajos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-20T00:00:00+00:00'::TIMESTAMPTZ, '9c8bbccda7a4ad5ac07b61efbc82af59a48b7da31f86f47421bfc12e0e161a16'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es una profesora muy graciosa y cómica. Además, su forma de explicar las cosas hacen la clase un poco menos aburridas. La calificación es la correcta, es puntual. Su forma de enseñar es oral y explicativa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'fd856c4b0a4f48cbc0961b48958fc74edaf5f589973ead6d9709b547f2cc24b0'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Loca, sarcástica y graciosa así se puede describir. Si ud se queda es por V-A-G-O/A. Haga todo lea las lecturas que tiene que exponer y ponga atención a las exposiciones para hacer los trabajos en clase son sencillos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'd88c5f0d7713586d9d233c2f7a067c91c7787bbc88f3629e1b6998a78c059bb8'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Una profesora muy graciosa y buena gente. Deja trabajos pero no son nada del otro mundo. Si no puede matricular con Mairim, esta profesora es una buena opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, '08fa06d83c563825854c29af2fe419472b8a9155aa36794c9dea013ee7366a9d'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'El ser humano más divertido que puede haber! Es super sarcástica y eso hace que las clases sean divertidas. Se hacen trabajos largos pero no difíciles. 100% recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '54decf7855fc6c816559b42f1b24db382a01dc3db0b82f1556ad9d8672aac010'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'LA MEJOR PROFE!! Es demasiado divertida y sarcástica, las clases no son para nada aburridas y si se trabaja bien en equipo, se pasa con 90 o más. Se hacen dos ensayos largos pero no difíciles. Matriculen con ella! No se van a arrepentir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-23T00:00:00+00:00'::TIMESTAMPTZ, '76a70876ecfabd6093db0ebdbc3b6cff8b2e31103b9c324e0ecc4d9d4613f294'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es una muy buena profe, con que usted cumpla con lo poco que ella pide ya es suficiente para pasar el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2017-11-13T00:00:00+00:00'::TIMESTAMPTZ, '2e3c77b76b35297990483e6b971b6138a9a1aa8ed17d913a3440f8cd483e8df3'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es un amor de profe,las clases son entretendrá y no deja muchos trabajos ni tareas. 100% recomendada'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '86f6499d3da5ff2848e0ab0bdb2d60e33878780472fd8b8f90dbbfcd07e5186f'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es una muy linda persona, muy loca y graciosa. Enseña muy bien, da resumenes de las lecturas. Explica bien y ayuda a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '225353d39d7c67126e57bd8d21c4b2753e88b529f1f6678f0468035d3025671d'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Clase sencilla, tal vez aburrida por los temas. Se hacen de vez en cuando tareas largas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '13fea4ae1f68068bed4a9e7ddd960ff740d7987b621bb85d784cc5560c3ebf0f'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Se toma el curso muy en serio pero tampoco quita demasiado tiempo, además esto ayuda mucho para el examen final colegiado. Da resúmenes de las lecturas. Es super divertida y buena gente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b90563b81904c01d397cb98a2f9f0a5e342e2c14bb03fb36077c217b99d6793b'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '6c520fd3d1b33b3b582f79d76c41defe613ebd71266c4b6658c5c21c8374ca4a'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Excelente profesora! Super linda y buena gente. Los temas son un poco aburridos, pero con esta profe se pasa genial. Es muy divertida. No califica duro. La recomiendo 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '4800888c95bd0e5eb8436ef2023f6e824954aaed4a17755d8ddf523dd03620d0'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Ella es una excelente Profe, muy loca y muy graciosa aunque es un curso que se pasa bien sí toca trabajar un poco se hacen como 2 trabajos grandes, 3 exposiciones y un trabajo final y de vez en cuando asigna como 4% en tareas cortas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '17394f008f6c6d8587be0ae05e5348f6bff9a0a677e03312fd1907cc9a986547'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'eb36430ace25811552008f9d72280e7f8fb5f31a15b428b295d178ed733d855d'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '215cf27d0dc5b3858db6dd267ddacb825847fcd434d83f120351a3acf808d33a'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'cc817056b91bb5be7512371a9328e963862fd0736966a82278d4ff2835829e7d'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Es muy simpática y alegre, las tareas que asigna son sencillas y cortas, el curso se pasa fácil y sin presiones.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-12T00:00:00+00:00'::TIMESTAMPTZ, '5a741e149275e7560582448b2abcd48e319d943e36dd3f9cb5044b4ab676d77a'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Muy entretenidas las clases.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '8d42bb5b0db77cfefc2d249d58683158c6ae4d4d72772e49b82f71e17a6c2506'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Excelente persona y profe. La clase es amena y no deja trabajos. Es muy paciente con los estudiantes y se interesa por el aprendizaje. No califica duro. La recomiendo montones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f367d8d156145fd0f834648bbefaa4a8ea9020ef9741fcda6745f8f8103348ac'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'El curso en sí es súper aburrido pero ella te ayuda con cuestionarios que son practicamente lo mismo que el examen, y si tenés una duda te explica mil veces si es necesario.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5ac13f652330ebafde38dd968e6acffcddbfbe6075abef43c0035dbe5a919916'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Excelente profe, no deja trabajos ni hace quices pero si quiere que le vaya bien en los examenes hay que hacer los cuestionarios que deja para cada lectura, sirven de mucho. Siempre esta dispuesta a ayudar y no califica duro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '3660fcca70f7c933e8691aedefeefb8360c8e48528426f8620c533063c814dec'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Es una muy buena profesora, hace cuestionamientos que de verdad lo dejan a uno pensando y vuelven el curso entretenido. Muchas lecturas, pero pocas tareas, solo para los exámenes hay que bretear un poquillo más. La recomiendo, pero asegúrese de tener buen grupo de trabajo para la investigación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '17e704eda707263cf68b1ffb9b45ef113a4a40dbc680cc0999f81cb2b2467bdf'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'f911723bb9fba07aa06201048aecfa50272e6ff9a466c5970998b6e3a7da8e19'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Es muy pura vida,ayuda bastante(al que le cae bien) hay que leer mucho, ya que hace preguntas muy específicas en los exámenes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'b66583a808a4a84e9921a444cb0b7fd61dda234b6fe49c8a76ad2fa145c97c53'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Las clases pueden ser larga y tediosas pero ella es una buena profesora. No excede en la dificultad del curso. Es llevadera.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'c483c25b9e04a3c87dd912b285b8211d08fe64ef65e3223dabfd4eb686e00df1'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Las clases son bastante llevaderas aunque pueden ser un poco cansadas a veces. Es buena gente y se preocupa por los estudiantes. Califica un poco duro los exámenes, y se tiene que estar dispuesto a leer los ensayos que asigna si se quiere pasar con buena calificación.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '16af8224dfa0c1bdd8df493e612976e7bd83415c1128af7e8dda77c61ef355a8'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '4989d27b0463196e750a3fbc1777bbdee3cf599535264abb6971920a51e2d614'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Excelente persona, es super vacilona y hace las clases entretenidas y divertidas. No hace pesado el curso y ayuda a los estudiantes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-05-10T00:00:00+00:00'::TIMESTAMPTZ, 'f56c866007fe75eef2a0134a6af05afa711871441aa3164af395de7cabff3877'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Las clases son muy entretenidas, se aprende y no deja trabajos y califica normal.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '8124b1fba11ffa8b01a9714cb27ed0858b9e5210795ffc91d2541d11dd4eb094'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Explica muy bien, hace la clase participativa y se preocupa porque usted entienda.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'e7dd3f3fc1ffa7b7e0f086ed7aa4393dc0afad1279b4eecacdeb37b7897cc2ff'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'La clase no es emocionante (también es culpa del contenido del curso). Deja que desear en la explicación de las lecturas porque pone a grupos a exponer.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'ec65eb8d1b0f15b03fdbc8f17ceaee28cf357399e1120f9bf7f163090366c2ad'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Le da mucha importancia al curso y hace examenes. Es Mejor otros profesores que hacen guias o ensayos en lugar de los exámenes por lo demás es muy Pura Vida y las clases son vacilonas'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-06T00:00:00+00:00'::TIMESTAMPTZ, '89e74ff65ac948fc9e70854d34a8d571b1f9c6f3a6edf791b5b4f35526964ab0'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Las clases son bastante entretenidas. Ella es muy alegre y la goza con el grupo. Revisa accesible los trabajos (no es un curso que uno pase ''matado'' el semestre. Se pasa relajado y pero se debate y se disfruta el curso)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, '4401ced74a4ecfca297c604c6a0757139788ce78ee145904aca8a8cc06c95991'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'Excelente profe, muy alegre, amistosa, explica bien, se aprende mucho, no califica rudo, muchos tareas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'af2ba1bef727bc68fa14947b08a1522b8fc5c0b1f2adbc93f057ac517928edf1'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (126::BIGINT, 'Hay que trabajar bastante. Es muy de izquierdas, a mi no me gustó el enfoque.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'e78be51a15fc70131544ccb1a22683b81d560a4e7d94e685890baf7910f53b1f'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (126::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '7b04b3ee61cc7f6e222a88dbacf482fb5f4fa1dc8bff393a5b79511248aa8387'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'excelente. ayuda y se roma el tiempo para explicar las lecturas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '0e87bad2db391ff5e5fbde31cd2fb578582bc70bb73943440353a79c26570eb7'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Es buena profe, y las clases son entretenidas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'd620fc500a127c21dec9b5a86077020dd9aacd46a0d85a5ab83476067fcb2c5d'::TEXT, ARRAY[981]::BIGINT[]),
    (126::BIGINT, 'EExcelente Profesora, clases divertidas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '15497fcc5e2c90263b8293fa7fe3cccc8521e2766a4a6e4f42aacef781aeea3f'::TEXT, ARRAY[559]::BIGINT[]),
    (126::BIGINT, 'Buena Profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'c90f4c0436d77d98f4b9fca0fe65009d24bd69ed5fab4167777c995ad1639e47'::TEXT, ARRAY[980, 2460]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
